149	    /**
150	     * The overall tax rate that actually ended up on the invoice: the sales tax and levy together as a
151	     * percentage of the total before tax, to two decimal places. It is below the headline rates when some
152	     * lines are tax-free, and zero when there is nothing before tax to charge it on.
153	     */
154	    public BigDecimal getEffectiveTaxPct() {
155	        BigDecimal totalExTax = getTotalExTax();
156	        if (totalExTax.signum() == 0) {
157	            return BigDecimal.ZERO.setScale(2);
158	        }
159	        return getTax().add(getLevy()).multiply(BigDecimal.valueOf(100)).divide(totalExTax, 2, RoundingMode.HALF_UP);
160	    }
