202	/**
203	 * Lifecycle stage of an invoice: DRAFT -> SENT -> PARTIAL -> PAID. Once sent, the stage is worked
204	 * out from the payments and credit notes recorded against the invoice. A sent invoice with nothing paid against it can
205	 * instead be cancelled, making it VOID: it stays on record but is no longer owed. A sent or part-paid invoice that
206	 * will never be paid can be written off as bad debt, making it WRITTEN_OFF: likewise kept on record but no longer owed.
207	 */
208	public enum InvoiceStatus {
209	    DRAFT,
210	    SENT,
211	    PARTIAL,
212	    PAID,
213	    VOID,
214	    WRITTEN_OFF;
215	
216	    /** Whether payments can still be recorded against an invoice at this stage. */
217	    public boolean isOwing() {
218	        return this == SENT || this == PARTIAL;
219	    }
220	
221	    /** Whether an invoice at this stage is closed without being paid (cancelled or written off), so nothing is owed. */
222	    public boolean isClosedUnpaid() {
223	        return this == VOID || this == WRITTEN_OFF;
224	    }
