187	   187	    public BigDecimal discountTakenBy(InvoiceDiscount discount) {
188	   188	        BigDecimal subtotal = getSubtotal();
189	   189	        BigDecimal left = subtotal;
190	   190	        for (InvoiceDiscount d : discountsInOrderTaken()) {
191	   191	            BigDecimal wanted = d.isPercentage() ? percentWanted(subtotal, d) : d.getDiscountAmount();
192	   192	            BigDecimal taken = wanted.min(left.max(BigDecimal.ZERO.setScale(2)));
193	   193	            if (d == discount) {
194	   194	                return taken;
