548	   548	     * out of the subtotal.
549	   549	     */
550	   550	    private BigDecimal discountOn(BigDecimal line) {
551	   551	        BigDecimal subtotal = getSubtotal();
552	   552	        BigDecimal pct = percentOf(line, uncappedPct(subtotal));
553	   553	        if (subtotal.signum() == 0) {
554	   554	            return pct;
555	   555	        }
556	   556	        BigDecimal flatShare = sharedDiscount(subtotal).multiply(line).divide(subtotal, 2, RoundingMode.HALF_UP);
557	   557	        return pct.add(flatShare);
558	   558	    }
559	   559	
560	   560	    /** The percentages not limited by a cap, added up (never more than 100). */
561	   561	    private BigDecimal uncappedPct(BigDecimal subtotal) {
562	   562	        return discounts.stream().filter(d -> d.isPercentage() && !isCappedAt(subtotal, d)).map(InvoiceDiscount::getDiscountPct)
563	   563	                .reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add).min(BigDecimal.valueOf(100).setScale(2));
564	   564	    }
565	   565	
566	   566	    /**
567	   567	     * What the flat discounts and the capped percentages actually take off the subtotal together, shared
568	   568	     * across the lines in proportion to what each charges.
569	   569	     */
570	   570	    private BigDecimal sharedDiscount(BigDecimal subtotal) {
571	   571	        return discounts.stream().filter(d -> !d.isPercentage() || isCappedAt(subtotal, d)).map(this::discountTakenBy)
572	   572	                .reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
573	   573	    }
574	   574	
575	   575	    /** The sales tax on one discounted taxable line (or inside it, when tax-inclusive), to the cent. */
576	   576	    private BigDecimal taxOn(BigDecimal line) {
577	   577	        return taxInclusive ? includedIn(line, taxPct) : percentOf(line, taxPct);
578	   578	    }
579	   579	
580	   580	    /** The levy on one discounted taxable line (or inside it, when tax-inclusive), to the cent. */
581	   581	    private BigDecimal levyOn(BigDecimal line) {
582	   582	        return taxInclusive ? includedIn(line, levyPct) : percentOf(line, levyPct);
583	   583	    }
584	   584	
585	   585	    private static BigDecimal percentOf(BigDecimal base, BigDecimal pct) {
586	   586	        return base.multiply(pct).divide(BigDecimal.valueOf(100), 2, RoundingMode.HALF_UP);
587	   587	    }
588	   588	
589	   589	    private void recalculateAmount() {
590	   590	        this.amount = getNetTotal().max(minimumCharge);
591	   591	    }
592	   592	
593	   593	    /** Marks this invoice as sent to the client. */
594	   594	    public void markSent() {
595	   595	        this.status = InvoiceStatus.SENT;
596	   596	    }
597	   597	
598	   598	    /** Cancels this invoice, so it is no longer owed. */
599	   599	    public void markVoid() {
600	   600	        this.status = InvoiceStatus.VOID;
601	   601	    }
602	   602	
603	   603	    /** Writes this invoice off as bad debt, so it is no longer owed. */
604	   604	    public void markWrittenOff() {
605	   605	        this.status = InvoiceStatus.WRITTEN_OFF;
606	   606	    }
607	   607	
608	   608	    /** What is left to pay on this invoice given the totals paid and credited against it; nothing once it is void or written off. */
609	   609	    public BigDecimal amountDue(BigDecimal paid, BigDecimal credited) {
610	   610	        return status.isClosedUnpaid() ? BigDecimal.ZERO.setScale(2) : amount.subtract(paid).subtract(credited);
611	   611	    }
612	   612	
613	   613	    /**
614	   614	     * This invoice's status given the totals paid and credited against it. Once sent, it is PAID when the
615	   615	     * payments and credit notes together clear the amount, PARTIAL once something has been paid or credited,
616	   616	     * otherwise still SENT. Drafts, void and written-off invoices keep their status, as does one marked paid by hand.
617	   617	     */
618	   618	    public InvoiceStatus statusFor(BigDecimal paid, BigDecimal credited) {
619	   619	        if (status == InvoiceStatus.DRAFT || status.isClosedUnpaid()) {
620	   620	            return status;
621	   621	        }
622	   622	        BigDecimal settled = paid.add(credited);
623	   623	        if (settled.compareTo(amount) >= 0 || (status == InvoiceStatus.PAID && settled.signum() == 0)) {
624	   624	            return InvoiceStatus.PAID;
625	   625	        }
626	   626	        return settled.signum() > 0 ? InvoiceStatus.PARTIAL : InvoiceStatus.SENT;
627	   627	    }
628	   628	
629	   629	    /**
630	   630	     * Works out this sent invoice's status from the totals paid and credited against it: PAID once the
631	   631	     * payments and credit notes cover the amount, PARTIAL once something has been settled, otherwise still SENT.
632	   632	     */
633	   633	    public void applySettledTotals(BigDecimal paid, BigDecimal credited) {
634	   634	        if (status == InvoiceStatus.DRAFT || status.isClosedUnpaid()) {
635	   635	            throw new IllegalStateException("A " + status.name().toLowerCase() + " invoice cannot be settled");
636	   636	        }
637	   637	        this.status = statusFor(paid, credited);
638	   638	    }
639	   639	}
