  1	package net.officefloor.hq.app.invoice;
  2	
  3	import jakarta.persistence.CascadeType;
  4	import jakarta.persistence.Column;
  5	import jakarta.persistence.Entity;
  6	import jakarta.persistence.EnumType;
  7	import jakarta.persistence.Enumerated;
  8	import jakarta.persistence.FetchType;
  9	import jakarta.persistence.GeneratedValue;
 10	import jakarta.persistence.GenerationType;
 11	import jakarta.persistence.Id;
 12	import jakarta.persistence.JoinColumn;
 13	import jakarta.persistence.ManyToOne;
 14	import jakarta.persistence.OneToMany;
 15	import jakarta.persistence.OrderBy;
 16	import jakarta.persistence.Table;
 17	import java.math.BigDecimal;
 18	import java.math.RoundingMode;
 19	import java.time.LocalDate;
 20	import java.time.temporal.ChronoUnit;
 21	import java.util.ArrayList;
 22	import java.util.List;
 23	import java.util.Optional;
 24	import java.util.function.UnaryOperator;
 25	import net.officefloor.hq.app.project.Project;
 26	
 27	/**
 28	 * An invoice raised against a project. It is built from line items, and can take several discounts off
 29	 * their sum before tax, each either a percentage or a flat amount (the percentages each taking their share
 30	 * of the subtotal first (a percentage capped at a maximum never taking off more than that), then the flat amounts, shared across the lines in proportion to what each
 31	 * charges; together never more than the subtotal), then add a percentage sales tax on what is left of the taxable lines only
 32	 * (tax-free lines are never taxed), and optionally a second tax (a levy) worked out on the same taxable base;
 33	 * its stored amount is always that subtotal less the discount plus the tax plus the levy, plus any flat
 34	 * surcharge (such as a handling fee), which is added on last and is never taxed.
 35	 * <p>
 36	 * Every figure is worked out line by line: each line is rounded to the cent first and the rounded lines
 37	 * are then added up, and the tax and levy are likewise worked out and rounded on each taxable line before
 38	 * being added up, so the totals are sums of rounded lines rather than a rounded sum.
 39	 * <p>
 40	 * A tax-inclusive invoice (for a client whose prices already include tax) instead works the tax and
 41	 * levy back out of the taxable lines after the discount: they are inside the price, so its amount is
 42	 * just the subtotal less the discount (plus any surcharge), and the taxable base is what is left once they are taken out.
 43	 * <p>
 44	 * A tax-exempt invoice (for a tax-exempt client) has no taxable lines at all: it carries no tax or levy
 45	 * whatever its lines or rates say, so its amount is the subtotal less the discount (plus any surcharge).
 46	 * <p>
 47	 * An invoice can carry a minimum charge: when its net total (everything above, worked out as usual) comes
 48	 * out under it, the minimum is billed instead, and the invoice records that the minimum was applied.
 49	 */
 50	@Entity
 51	@Table(name = "invoice")
 52	public class Invoice {
 53	
 54	    @Id
 55	    @GeneratedValue(strategy = GenerationType.IDENTITY)
 56	    private Long id;
 57	
 58	    @ManyToOne(fetch = FetchType.LAZY, optional = false)
 59	    @JoinColumn(name = "project_id", nullable = false)
 60	    private Project project;
 61	
 62	    @Column(nullable = false, precision = 12, scale = 2)
 63	    private BigDecimal amount = BigDecimal.ZERO.setScale(2);
 64	
 65	    @Column(name = "tax_pct", nullable = false, precision = 5, scale = 2)
 66	    private BigDecimal taxPct = BigDecimal.ZERO.setScale(2);
 67	
 68	    @Column(name = "levy_pct", nullable = false, precision = 5, scale = 2)
 69	    private BigDecimal levyPct = BigDecimal.ZERO.setScale(2);
 70	
 71	    /** A flat amount (such as a handling fee) added to the total after tax; zero when there is none. */
 72	    @Column(nullable = false, precision = 12, scale = 2)
 73	    private BigDecimal surcharge = BigDecimal.ZERO.setScale(2);
 74	
 75	    /** The least the invoice bills; zero when there is no minimum charge. */
 76	    @Column(name = "minimum_charge", nullable = false, precision = 12, scale = 2)
 77	    private BigDecimal minimumCharge = BigDecimal.ZERO.setScale(2);
 78	
 79	    /** Whether the prices already include the tax and levy, so they are backed out rather than added on. */
 80	    @Column(name = "tax_inclusive", nullable = false)
 81	    private boolean taxInclusive;
 82	
 83	    /** Whether the invoice is for a tax-exempt client, so it carries no tax or levy whatever its lines say. */
 84	    @Column(name = "tax_exempt", nullable = false)
 85	    private boolean taxExempt;
 86	
 87	    /** The percentage taken off what is owed when paid early; zero when no early-payment discount is offered. */
 88	    @Column(name = "early_payment_pct", nullable = false, precision = 5, scale = 2)
 89	    private BigDecimal earlyPaymentPct = BigDecimal.ZERO.setScale(2);
 90	
 91	    /** How many days after being issued the invoice must be paid within to get the early-payment discount. */
 92	    @Column(name = "early_payment_days", nullable = false)
 93	    private int earlyPaymentDays;
 94	
 95	    /** The late fee charged for each day the invoice is overdue once sent; zero when none is charged. */
 96	    @Column(name = "late_fee_per_day", nullable = false, precision = 12, scale = 2)
 97	    private BigDecimal lateFeePerDay = BigDecimal.ZERO.setScale(2);
 98	
 99	    @Enumerated(EnumType.STRING)
100	    @Column(nullable = false, length = 16)
101	    private InvoiceStatus status = InvoiceStatus.DRAFT;
102	
103	    @Column(name = "issued_date", nullable = false)
104	    private LocalDate issuedDate;
105	
106	    @Column(name = "due_date", nullable = false)
107	    private LocalDate dueDate;
108	
109	    @OneToMany(mappedBy = "invoice", cascade = CascadeType.ALL, orphanRemoval = true)
110	    @OrderBy("id")
111	    private List<InvoiceLineItem> lineItems = new ArrayList<>();
112	
113	    /** The discounts taken off the subtotal before tax, in the order they were added. */
114	    @OneToMany(mappedBy = "invoice", cascade = CascadeType.ALL, orphanRemoval = true)
115	    @OrderBy("id")
116	    private List<InvoiceDiscount> discounts = new ArrayList<>();
117	
118	    protected Invoice() {
119	    }
120	
121	    public Invoice(Project project, LocalDate issuedDate, LocalDate dueDate) {
122	        this.project = project;
123	        this.issuedDate = issuedDate;
124	        this.dueDate = dueDate;
125	        this.taxInclusive = project.getClient().isTaxInclusive();
126	        this.taxExempt = project.getClient().isTaxExempt();
127	    }
128	
129	    public Long getId() {
130	        return id;
131	    }
132	
133	    public Project getProject() {
134	        return project;
135	    }
136	
137	    public BigDecimal getAmount() {
138	        return amount;
139	    }
140	
141	    /**
142	     * The total before tax: the amount owed less the sales tax and levy, whether they were added on or
143	     * are included in the prices.
144	     */
145	    public BigDecimal getTotalExTax() {
146	        return amount.subtract(getTax()).subtract(getLevy());
147	    }
148	
149	    /**
150	     * The overall tax rate that actually ended up on the invoice: the sales tax and levy together as a
151	     * percentage of the total before tax, to two decimal places. It is below the headline rates when some
152	     * lines are tax-free, and zero when there is nothing before tax to charge it on.
153	     */
154	    public BigDecimal getEffectiveTaxPct() {
155	        BigDecimal totalExTax = getTotalExTax();
156	        if (totalExTax.signum() == 0) {
157	            return BigDecimal.ZERO.setScale(2);
158	        }
159	        return getTax().add(getLevy()).multiply(BigDecimal.valueOf(100)).divide(totalExTax, 2, RoundingMode.HALF_UP);
160	    }
161	
162	    /** The discounts on this invoice, in the order they were added. */
163	    public List<InvoiceDiscount> getDiscounts() {
164	        return List.copyOf(discounts);
165	    }
166	
167	    /**
168	     * The percentages taken off the subtotal, added up (never more than 100); zero when there is no
169	     * percentage discount.
170	     */
171	    public BigDecimal getDiscountPct() {
172	        return discounts.stream().map(InvoiceDiscount::getDiscountPct).reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add)
173	                .min(BigDecimal.valueOf(100).setScale(2));
174	    }
175	
176	    /** The flat amounts asked to be taken off the subtotal, added up; zero when there is no flat discount. */
177	    public BigDecimal getDiscountAmount() {
178	        return discounts.stream().map(InvoiceDiscount::getDiscountAmount).reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
179	    }
180	
181	    /**
182	     * How much one of this invoice's discounts actually takes off the subtotal, to the cent. The
183	     * percentages are taken first, each its share of the subtotal (never more than its cap, if it has
184	     * one), then the flat amounts in the order they were added; none takes off more than is left after
185	     * those before it.
186	     */
187	    public BigDecimal discountTakenBy(InvoiceDiscount discount) {
188	        BigDecimal subtotal = getSubtotal();
189	        BigDecimal left = subtotal;
190	        for (InvoiceDiscount d : discountsInOrderTaken()) {
191	            BigDecimal wanted = d.isPercentage() ? percentWanted(subtotal, d) : d.getDiscountAmount();
192	            BigDecimal taken = wanted.min(left.max(BigDecimal.ZERO.setScale(2)));
193	            if (d == discount) {
194	                return taken;
195	            }
196	            left = left.subtract(taken);
197	        }
198	        return BigDecimal.ZERO.setScale(2);
199	    }
200	
201	    /** What a percentage discount asks to take off the subtotal: its share, never more than its cap. */
202	    private static BigDecimal percentWanted(BigDecimal subtotal, InvoiceDiscount discount) {
203	        BigDecimal share = percentOf(subtotal, discount.getDiscountPct());
204	        return isCappedAt(subtotal, discount) ? share.min(discount.getDiscountCap()) : share;
205	    }
206	
207	    /** Whether a discount's cap limits what it takes off the given subtotal. */
208	    private static boolean isCappedAt(BigDecimal subtotal, InvoiceDiscount discount) {
209	        return discount.getDiscountCap() != null
210	                && percentOf(subtotal, discount.getDiscountPct()).compareTo(discount.getDiscountCap()) > 0;
211	    }
212	
213	    /** The percentage discounts first, then the flat ones, each in the order they were added. */
214	    private List<InvoiceDiscount> discountsInOrderTaken() {
215	        List<InvoiceDiscount> ordered = new ArrayList<>(discounts.stream().filter(InvoiceDiscount::isPercentage).toList());
216	        ordered.addAll(discounts.stream().filter(d -> !d.isPercentage()).toList());
217	        return ordered;
218	    }
219	
220	    /**
221	     * What the line items add up to, before the invoice's discount: the sum of each line after its own
222	     * discount, rounded to the cent.
223	     */
224	    public BigDecimal getSubtotal() {
225	        return lineItems.stream().map(InvoiceLineItem::getAmount).reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
226	    }
227	
228	    /** How much the discounts take off the subtotal together (what each takes off, added up), to the cent. */
229	    public BigDecimal getDiscount() {
230	        return discounts.stream().map(this::discountTakenBy).reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
231	    }
232	
233	    /**
234	     * How much the client saves on this invoice: every discount added together, both what the lines take
235	     * off themselves and what the invoice's discounts take off the subtotal, to the cent.
236	     */
237	    public BigDecimal getTotalSavings() {
238	        BigDecimal lineSavings = lineItems.stream().map(l -> l.getGrossAmount().subtract(l.getAmount()))
239	                .reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
240	        return lineSavings.add(getDiscount());
241	    }
242	
243	    /** The sales tax percentage added after the discount; zero when there is no tax. */
244	    public BigDecimal getTaxPct() {
245	        return taxPct;
246	    }
247	
248	    /** Whether the prices already include the tax and levy, so they are worked back out rather than added on. */
249	    public boolean isTaxInclusive() {
250	        return taxInclusive;
251	    }
252	
253	    /** Whether the invoice is for a tax-exempt client, so none of its lines are taxed. */
254	    public boolean isTaxExempt() {
255	        return taxExempt;
256	    }
257	
258	    /**
259	     * What the sales tax is charged on: the taxable lines (leaving out tax-free ones) less the discount
260	     * taken off them, to the cent. On a tax-inclusive invoice that is what is left of them once the tax
261	     * and levy inside them are taken out.
262	     */
263	    public BigDecimal getTaxableBase() {
264	        BigDecimal gross = getDiscountedTaxable();
265	        return taxInclusive ? gross.subtract(getTax()).subtract(getLevy()) : gross;
266	    }
267	
268	    /**
269	     * How much sales tax is added on the taxable base (or is inside it, when tax-inclusive): the tax on
270	     * each taxable line rounded to the cent, added up.
271	     */
272	    public BigDecimal getTax() {
273	        return sumOverTaxableLines(this::taxOn);
274	    }
275	
276	    /** The levy (second tax) percentage added on top of the sales tax; zero when there is no levy. */
277	    public BigDecimal getLevyPct() {
278	        return levyPct;
279	    }
280	
281	    /**
282	     * How much levy is added on the taxable base (or is inside it, when tax-inclusive): the levy on each
283	     * taxable line rounded to the cent, added up.
284	     */
285	    public BigDecimal getLevy() {
286	        return sumOverTaxableLines(this::levyOn);
287	    }
288	
289	    /** The flat amount (such as a handling fee) added to the total after tax; zero when there is none. */
290	    public BigDecimal getSurcharge() {
291	        return surcharge;
292	    }
293	
294	    /** The least this invoice bills; zero when there is no minimum charge. */
295	    public BigDecimal getMinimumCharge() {
296	        return minimumCharge;
297	    }
298	
299	    /**
300	     * What the invoice comes to before any minimum charge: the subtotal less the discount plus the tax and
301	     * levy (unless they are inside the prices), plus the surcharge.
302	     */
303	    public BigDecimal getNetTotal() {
304	        BigDecimal discounted = getSubtotal().subtract(getDiscount());
305	        return (taxInclusive ? discounted : discounted.add(getTax()).add(getLevy())).add(surcharge);
306	    }
307	
308	    /** Whether the net total came out under the minimum charge, so the minimum is billed instead. */
309	    public boolean isMinimumApplied() {
310	        return getNetTotal().compareTo(minimumCharge) < 0;
311	    }
312	
313	    /** The taxable lines (leaving out tax-free ones), each less the discount taken off it, added up. */
314	    private BigDecimal getDiscountedTaxable() {
315	        return sumOverTaxableLines(line -> line);
316	    }
317	
318	    /**
319	     * Works a figure out on each taxable line after its discount, to the cent, and adds them up. A
320	     * tax-exempt invoice has no taxable lines.
321	     */
322	    private BigDecimal sumOverTaxableLines(UnaryOperator<BigDecimal> perLine) {
323	        return lineItems.stream().filter(l -> !taxExempt && !l.isTaxExempt()).map(InvoiceLineItem::getAmount)
324	                .map(amount -> perLine.apply(amount.subtract(discountOn(amount))))
325	                .reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
326	    }
327	
328	    /**
329	     * The part of a tax-inclusive price that is the given percentage, worked back out of it: the price
330	     * divided in proportion to the sales tax and levy rates it includes (e.g. 20% tax in 120 is 20).
331	     */
332	    private BigDecimal includedIn(BigDecimal price, BigDecimal pct) {
333	        BigDecimal grossPct = BigDecimal.valueOf(100).add(taxPct).add(levyPct);
334	        return price.multiply(pct).divide(grossPct, 2, RoundingMode.HALF_UP);
335	    }
336	
337	    /** The percentage taken off what is owed when paid early; zero when none is offered. */
338	    public BigDecimal getEarlyPaymentPct() {
339	        return earlyPaymentPct;
340	    }
341	
342	    /** How many days after being issued the invoice must be paid within to get the early-payment discount. */
343	    public int getEarlyPaymentDays() {
344	        return earlyPaymentDays;
345	    }
346	
347	    /** Whether an early-payment discount is offered: a percentage off when paid within some days. */
348	    public boolean offersEarlyPayment() {
349	        return earlyPaymentPct.signum() > 0 && earlyPaymentDays > 0;
350	    }
351	
352	    /** The last day the invoice can be paid to get the early-payment discount; null when none is offered. */
353	    public LocalDate getEarlyPaymentBy() {
354	        return offersEarlyPayment() ? issuedDate.plusDays(earlyPaymentDays) : null;
355	    }
356	
357	    /**
358	     * The reduced amount to pay when settling early: the amount less the early-payment percentage of it,
359	     * to the cent; null when no early-payment discount is offered.
360	     */
361	    public BigDecimal getEarlyPaymentAmount() {
362	        return offersEarlyPayment() ? amount.subtract(percentOf(amount, earlyPaymentPct)) : null;
363	    }
364	
365	    public InvoiceStatus getStatus() {
366	        return status;
367	    }
368	
369	    public LocalDate getIssuedDate() {
370	        return issuedDate;
371	    }
372	
373	    public LocalDate getDueDate() {
374	        return dueDate;
375	    }
376	
377	    public List<InvoiceLineItem> getLineItems() {
378	        return List.copyOf(lineItems);
379	    }
380	
381	    /** Adds a line to this invoice and reworks its amount to include what the line charges. */
382	    public InvoiceLineItem addLineItem(String description, BigDecimal qty, String unit, BigDecimal unitPrice) {
383	        return addLineItem(description, qty, unit, unitPrice, false, BigDecimal.ZERO);
384	    }
385	
386	    /**
387	     * Adds a line, taxable or tax-free and with any discount of its own, to this invoice and reworks its
388	     * amount to include what the line charges after that discount.
389	     */
390	    public InvoiceLineItem addLineItem(String description, BigDecimal qty, String unit, BigDecimal unitPrice,
391	            boolean taxExempt, BigDecimal discountPct) {
392	        InvoiceLineItem item = new InvoiceLineItem(this, description, qty, unit, unitPrice, taxExempt, discountPct);
393	        lineItems.add(item);
394	        recalculateAmount();
395	        return item;
396	    }
397	
398	    /** Changes one of this invoice's lines and reworks its amount to match. */
399	    public void updateLineItem(InvoiceLineItem item, String description, BigDecimal qty, String unit,
400	            BigDecimal unitPrice, boolean taxExempt, BigDecimal discountPct) {
401	        item.update(description, qty, unit, unitPrice, taxExempt, discountPct);
402	        recalculateAmount();
403	    }
404	
405	    /** Removes a line from this invoice and reworks its amount to no longer include what the line charged. */
406	    public void removeLineItem(InvoiceLineItem item) {
407	        lineItems.remove(item);
408	        recalculateAmount();
409	    }
410	
411	    /** The line on this invoice with the given id, if there is one. */
412	    public Optional<InvoiceLineItem> findLineItem(Long lineItemId) {
413	        return lineItems.stream().filter(l -> l.getId().equals(lineItemId)).findFirst();
414	    }
415	
416	    /** Replaces this invoice's discounts with a single percentage and reworks its amount to match. */
417	    public void applyDiscount(BigDecimal discountPct) {
418	        applyDiscount(discountPct, BigDecimal.ZERO);
419	    }
420	
421	    /**
422	     * Replaces this invoice's discounts with a single one, either a percentage or a flat amount (the other
423	     * being zero; zero for both leaves no discount), and reworks its amount to match.
424	     */
425	    public void applyDiscount(BigDecimal discountPct, BigDecimal discountAmount) {
426	        applyDiscount(discountPct, discountAmount, null);
427	    }
428	
429	    /**
430	     * Replaces this invoice's discounts with a single one, either a percentage (optionally capped at the
431	     * most it takes off) or a flat amount, and reworks its amount to match.
432	     */
433	    public void applyDiscount(BigDecimal discountPct, BigDecimal discountAmount, BigDecimal discountCap) {
434	        InvoiceDiscount discount = new InvoiceDiscount(this, discountPct, discountAmount, discountCap);
435	        discounts.clear();
436	        if (discountPct.signum() != 0 || discountAmount.signum() != 0) {
437	            discounts.add(discount);
438	        }
439	        recalculateAmount();
440	    }
441	
442	    /**
443	     * Adds another discount to this invoice, either a percentage or a flat amount (the other being zero),
444	     * and reworks its amount to match.
445	     */
446	    public InvoiceDiscount addDiscount(BigDecimal discountPct, BigDecimal discountAmount) {
447	        return addDiscount(discountPct, discountAmount, null);
448	    }
449	
450	    /**
451	     * Adds another discount to this invoice, either a percentage (optionally capped at the most it takes
452	     * off) or a flat amount, and reworks its amount to match.
453	     */
454	    public InvoiceDiscount addDiscount(BigDecimal discountPct, BigDecimal discountAmount, BigDecimal discountCap) {
455	        if (discountPct.signum() == 0 && discountAmount.signum() == 0) {
456	            throw new IllegalArgumentException("A discount takes off a percentage or a flat amount");
457	        }
458	        InvoiceDiscount discount = new InvoiceDiscount(this, discountPct, discountAmount, discountCap);
459	        discounts.add(discount);
460	        recalculateAmount();
461	        return discount;
462	    }
463	
464	    /** Removes a discount from this invoice and reworks its amount to match. */
465	    public void removeDiscount(InvoiceDiscount discount) {
466	        discounts.remove(discount);
467	        recalculateAmount();
468	    }
469	
470	    /** The discount on this invoice with the given id, if there is one. */
471	    public Optional<InvoiceDiscount> findDiscount(Long discountId) {
472	        return discounts.stream().filter(d -> d.getId().equals(discountId)).findFirst();
473	    }
474	
475	    /** Sets the sales tax percentage added to this invoice and reworks its amount to match. */
476	    public void applyTax(BigDecimal taxPct) {
477	        this.taxPct = taxPct.setScale(2, RoundingMode.HALF_UP);
478	        recalculateAmount();
479	    }
480	
481	    /** Sets whether this invoice's prices already include tax and reworks its amount to match. */
482	    public void applyTaxInclusive(boolean taxInclusive) {
483	        this.taxInclusive = taxInclusive;
484	        recalculateAmount();
485	    }
486	
487	    /** Sets whether this invoice is for a tax-exempt client and reworks its amount to match. */
488	    public void applyTaxExempt(boolean taxExempt) {
489	        this.taxExempt = taxExempt;
490	        recalculateAmount();
491	    }
492	
493	    /** Sets the levy (second tax) percentage added to this invoice and reworks its amount to match. */
494	    public void applyLevy(BigDecimal levyPct) {
495	        this.levyPct = levyPct.setScale(2, RoundingMode.HALF_UP);
496	        recalculateAmount();
497	    }
498	
499	    /** Sets the flat surcharge (such as a handling fee) added to this invoice and reworks its amount to match. */
500	    public void applySurcharge(BigDecimal surcharge) {
501	        this.surcharge = surcharge.setScale(2, RoundingMode.HALF_UP);
502	        recalculateAmount();
503	    }
504	
505	    /** Sets the minimum charge billed on this invoice and reworks its amount to match. */
506	    public void applyMinimumCharge(BigDecimal minimumCharge) {
507	        this.minimumCharge = minimumCharge.setScale(2, RoundingMode.HALF_UP);
508	        recalculateAmount();
509	    }
510	
511	    /** Sets the late fee charged for each day this invoice is overdue. It does not change the amount invoiced. */
512	    public void applyLateFee(BigDecimal lateFeePerDay) {
513	        this.lateFeePerDay = lateFeePerDay.setScale(2, RoundingMode.HALF_UP);
514	    }
515	
516	    public BigDecimal getLateFeePerDay() {
517	        return lateFeePerDay;
518	    }
519	
520	    /**
521	     * How many days past its due date the invoice is on the given day; zero unless it has been sent and
522	     * is still owed (sent or part paid).
523	     */
524	    public long daysLate(InvoiceStatus status, LocalDate today) {
525	        if (status != InvoiceStatus.SENT && status != InvoiceStatus.PARTIAL) {
526	            return 0;
527	        }
528	        return Math.max(0, ChronoUnit.DAYS.between(dueDate, today));
529	    }
530	
531	    /** The late fee accrued by the given day: the fee per day times the days the invoice is overdue. */
532	    public BigDecimal lateFee(InvoiceStatus status, LocalDate today) {
533	        return lateFeePerDay.multiply(BigDecimal.valueOf(daysLate(status, today))).setScale(2, RoundingMode.HALF_UP);
534	    }
535	
536	    /**
537	     * Sets the early-payment discount offered on this invoice: the percentage taken off if it is paid
538	     * within the given number of days of being issued. It does not change the amount owed.
539	     */
540	    public void applyEarlyPayment(BigDecimal earlyPaymentPct, int earlyPaymentDays) {
541	        this.earlyPaymentPct = earlyPaymentPct.setScale(2, RoundingMode.HALF_UP);
542	        this.earlyPaymentDays = earlyPaymentDays;
543	    }
544	
545	    /**
546	     * The discount taken off one line, to the cent: the uncapped percentages together, plus its share of
547	     * what the flat amounts and the capped percentages take off in proportion to what the line charges
548	     * out of the subtotal.
549	     */
550	    private BigDecimal discountOn(BigDecimal line) {
551	        BigDecimal subtotal = getSubtotal();
552	        BigDecimal pct = percentOf(line, uncappedPct(subtotal));
553	        if (subtotal.signum() == 0) {
554	            return pct;
555	        }
556	        BigDecimal flatShare = sharedDiscount(subtotal).multiply(line).divide(subtotal, 2, RoundingMode.HALF_UP);
557	        return pct.add(flatShare);
558	    }
559	
560	    /** The percentages not limited by a cap, added up (never more than 100). */
561	    private BigDecimal uncappedPct(BigDecimal subtotal) {
562	        return discounts.stream().filter(d -> d.isPercentage() && !isCappedAt(subtotal, d)).map(InvoiceDiscount::getDiscountPct)
563	                .reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add).min(BigDecimal.valueOf(100).setScale(2));
564	    }
565	
566	    /**
567	     * What the flat discounts and the capped percentages actually take off the subtotal together, shared
568	     * across the lines in proportion to what each charges.
569	     */
570	    private BigDecimal sharedDiscount(BigDecimal subtotal) {
571	        return discounts.stream().filter(d -> !d.isPercentage() || isCappedAt(subtotal, d)).map(this::discountTakenBy)
572	                .reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
573	    }
574	
575	    /** The sales tax on one discounted taxable line (or inside it, when tax-inclusive), to the cent. */
576	    private BigDecimal taxOn(BigDecimal line) {
577	        return taxInclusive ? includedIn(line, taxPct) : percentOf(line, taxPct);
578	    }
579	
580	    /** The levy on one discounted taxable line (or inside it, when tax-inclusive), to the cent. */
581	    private BigDecimal levyOn(BigDecimal line) {
582	        return taxInclusive ? includedIn(line, levyPct) : percentOf(line, levyPct);
583	    }
584	
585	    private static BigDecimal percentOf(BigDecimal base, BigDecimal pct) {
586	        return base.multiply(pct).divide(BigDecimal.valueOf(100), 2, RoundingMode.HALF_UP);
587	    }
588	
589	    private void recalculateAmount() {
590	        this.amount = getNetTotal().max(minimumCharge);
591	    }
592	
593	    /** Marks this invoice as sent to the client. */
594	    public void markSent() {
595	        this.status = InvoiceStatus.SENT;
596	    }
597	
598	    /** Cancels this invoice, so it is no longer owed. */
599	    public void markVoid() {
600	        this.status = InvoiceStatus.VOID;
601	    }
602	
603	    /** Writes this invoice off as bad debt, so it is no longer owed. */
604	    public void markWrittenOff() {
605	        this.status = InvoiceStatus.WRITTEN_OFF;
606	    }
607	
608	    /** What is left to pay on this invoice given the totals paid and credited against it; nothing once it is void or written off. */
609	    public BigDecimal amountDue(BigDecimal paid, BigDecimal credited) {
610	        return status.isClosedUnpaid() ? BigDecimal.ZERO.setScale(2) : amount.subtract(paid).subtract(credited);
611	    }
612	
613	    /**
614	     * This invoice's status given the totals paid and credited against it. Once sent, it is PAID when the
615	     * payments and credit notes together clear the amount, PARTIAL once something has been paid or credited,
616	     * otherwise still SENT. Drafts, void and written-off invoices keep their status, as does one marked paid by hand.
617	     */
618	    public InvoiceStatus statusFor(BigDecimal paid, BigDecimal credited) {
619	        if (status == InvoiceStatus.DRAFT || status.isClosedUnpaid()) {
620	            return status;
621	        }
622	        BigDecimal settled = paid.add(credited);
623	        if (settled.compareTo(amount) >= 0 || (status == InvoiceStatus.PAID && settled.signum() == 0)) {
624	            return InvoiceStatus.PAID;
625	        }
626	        return settled.signum() > 0 ? InvoiceStatus.PARTIAL : InvoiceStatus.SENT;
627	    }
628	
629	    /**
630	     * Works out this sent invoice's status from the totals paid and credited against it: PAID once the
631	     * payments and credit notes cover the amount, PARTIAL once something has been settled, otherwise still SENT.
632	     */
633	    public void applySettledTotals(BigDecimal paid, BigDecimal credited) {
634	        if (status == InvoiceStatus.DRAFT || status.isClosedUnpaid()) {
635	            throw new IllegalStateException("A " + status.name().toLowerCase() + " invoice cannot be settled");
636	        }
637	        this.status = statusFor(paid, credited);
638	    }
639	}

