 61	        this.fxRates = fxRates;
 62	        this.audit = audit;
 63	        this.clock = clock;
 64	    }
 65	
 66	    @Transactional(readOnly = true)
 67	    public List<InvoiceResponse> listForProject(Long projectId) {
 68	        if (!projects.existsById(projectId)) {
 69	            throw new ResponseStatusException(HttpStatus.NOT_FOUND, "Unknown job");
 70	        }
 71	        List<Invoice> found = invoices.findByProjectIdOrderById(projectId);
 72	        Map<Long, BigDecimal> paid = paidByInvoice(found);
 73	        Map<Long, BigDecimal> credited = creditedByInvoice(found);
 74	        return found.stream()
 75	                .map(i -> InvoiceResponse.from(i, paid.getOrDefault(i.getId(), BigDecimal.ZERO),
 76	                        credited.getOrDefault(i.getId(), BigDecimal.ZERO)))
 77	                .toList();
 78	    }
 79	
 80	    /**
 81	     * A client's statement: every invoice across their projects with what is left to pay on each, and
 82	     * the total they still owe, also grouped by job with a subtotal per job. Drafts are listed but not owed, as they have not been sent, nor are
 83	     * void invoices, as they have been cancelled.
 84	     */
 85	    @Transactional(readOnly = true)
 86	    public ClientStatementResponse statementForClient(Long clientId) {
 87	        Client client = clients.findById(clientId)
 88	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "Unknown client"));
 89	        List<Invoice> found = invoices.findByClientIdWithProject(clientId);
 90	        Map<Long, BigDecimal> paid = paidByInvoice(found);
 91	        Map<Long, BigDecimal> credited = creditedByInvoice(found);
 92	        List<ClientStatementResponse.Line> lines = found.stream()
 93	                .map(i -> ClientStatementResponse.Line.from(i, paid.getOrDefault(i.getId(), BigDecimal.ZERO),
 94	                        credited.getOrDefault(i.getId(), BigDecimal.ZERO)))
 95	                .toList();
 96	        return ClientStatementResponse.from(client.getId(), client.getName(), client.getCurrency(), lines,
 97	                accountEntries(clientId, found));
 98	    }
 99	
100	    /**
101	     * What a client owed as at the end of the given day: the running account counting only the entries dated on or
102	     * before it.
103	     */
104	    @Transactional(readOnly = true)
105	    public ClientBalanceAsOfResponse balanceAsOf(Long clientId, LocalDate asOf) {
106	        Client client = clients.findById(clientId)
107	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "Unknown client"));
108	        List<Invoice> found = invoices.findByClientIdWithProject(clientId);
109	        BigDecimal balance = accountEntries(clientId, found).stream()
110	                .filter(e -> e.date() != null && !e.date().isAfter(asOf))
111	                .map(StatementEntry::change)
112	                .reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
113	        return new ClientBalanceAsOfResponse(client.getId(), client.getCurrency(), asOf, balance);
114	    }
115	
116	    /**
117	     * How old a client's debt is as at today: what is left to pay on each owed invoice (not a draft, void or written
118	     * off) counted against how many days past its due date it is.
119	     */
120	    @Transactional(readOnly = true)
121	    public ClientAgingResponse agingForClient(Long clientId) {
122	        Client client = clients.findById(clientId)
123	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "Unknown client"));
124	        LocalDate today = LocalDate.now(clock);
125	        List<Invoice> found = invoices.findByClientIdWithProject(clientId);
126	        Map<Long, BigDecimal> paid = paidByInvoice(found);
127	        Map<Long, BigDecimal> credited = creditedByInvoice(found);
128	        BigDecimal current = BigDecimal.ZERO.setScale(2);
129	        BigDecimal days30To60 = BigDecimal.ZERO.setScale(2);
130	        BigDecimal days60Plus = BigDecimal.ZERO.setScale(2);
131	        for (Invoice invoice : found) {
132	            BigDecimal invoicePaid = paid.getOrDefault(invoice.getId(), BigDecimal.ZERO);
133	            BigDecimal invoiceCredited = credited.getOrDefault(invoice.getId(), BigDecimal.ZERO);
134	            InvoiceStatus status = invoice.statusFor(invoicePaid, invoiceCredited);
135	            if (status == InvoiceStatus.DRAFT || status.isClosedUnpaid()) {
136	                continue;
137	            }
138	            BigDecimal due = invoice.amountDue(invoicePaid, invoiceCredited);
139	            if (due.signum() <= 0) {
140	                continue;
141	            }
142	            long overdue = invoice.getDueDate() == null ? 0
143	                    : ChronoUnit.DAYS.between(invoice.getDueDate(), today);
144	            if (overdue > 60) {
145	                days60Plus = days60Plus.add(due);
146	            } else if (overdue > 30) {
147	                days30To60 = days30To60.add(due);
148	            } else {
149	                current = current.add(due);
150	            }
151	        }
152	        return new ClientAgingResponse(client.getId(), client.getCurrency(), today,
153	                current.setScale(2, RoundingMode.HALF_UP), days30To60.setScale(2, RoundingMode.HALF_UP),
154	                days60Plus.setScale(2, RoundingMode.HALF_UP));
155	    }
156	
157	    /**
158	     * The entries on a client's running account. Drafts have not been sent and void invoices were cancelled, so
159	     * neither is charged. A payment made out of held deposits is left out, as the deposit was already credited
160	     * when it was paid in.
161	     */
162	    private List<StatementEntry> accountEntries(Long clientId, List<Invoice> found) {
163	        List<StatementEntry> entries = new ArrayList<>();
164	        List<Long> sent = new ArrayList<>();
165	        for (Invoice invoice : found) {
166	            if (invoice.getStatus() == InvoiceStatus.DRAFT) {
167	                continue;
168	            }
169	            sent.add(invoice.getId());
170	            if (invoice.getStatus() != InvoiceStatus.VOID) {
171	                entries.add(StatementEntry.charge(StatementEntry.Kind.INVOICE, invoice.getId(), invoice.getId(),
172	                        invoice.getIssuedDate(), "Invoice #" + invoice.getId(), invoice.getAmount()));
173	            }
174	        }
175	        if (!sent.isEmpty()) {
176	            for (Payment payment : payments.findByInvoiceIdIn(sent)) {
177	                if (payment.getDepositApplicationId() == null) {
178	                    entries.add(StatementEntry.credit(StatementEntry.Kind.PAYMENT, payment.getId(), payment.getInvoiceId(),
179	                            payment.getDate(), "Payment on invoice #" + payment.getInvoiceId(), payment.getAmount()));
180	                }
181	            }
182	            for (CreditNote note : creditNotes.findByInvoiceIdIn(sent)) {
183	                entries.add(StatementEntry.credit(StatementEntry.Kind.CREDIT_NOTE, note.getId(), note.getInvoiceId(),
184	                        LocalDate.ofInstant(note.getIssuedAt(), ZoneOffset.UTC),
185	                        "Credit note on invoice #" + note.getInvoiceId(), note.getAmount()));
186	            }
187	        }
188	        for (Deposit deposit : deposits.findByClientIdOrderByDateAscIdAsc(clientId)) {
189	            entries.add(StatementEntry.credit(StatementEntry.Kind.DEPOSIT, deposit.getId(), null, deposit.getDate(),
190	                    "Deposit", deposit.getAmount()));
191	        }
192	        for (Refund refund : refunds.findByClientIdOrderByDateDescIdDesc(clientId)) {
193	            entries.add(StatementEntry.charge(StatementEntry.Kind.REFUND, refund.getId(), null, refund.getDate(),
194	                    "Refund", refund.getAmount()));
195	        }
196	        return entries;
197	    }
198	
199	    private Map<Long, BigDecimal> paidByInvoice(List<Invoice> found) {
200	        return found.isEmpty() ? Map.of()
201	                : payments.sumAmountByInvoiceIds(found.stream().map(Invoice::getId).toList()).stream()
202	                        .collect(Collectors.toMap(PaymentRepository.InvoicePaidTotal::getInvoiceId,
203	                                PaymentRepository.InvoicePaidTotal::getPaid));
204	    }
205	
206	    private Map<Long, BigDecimal> creditedByInvoice(List<Invoice> found) {
207	        return found.isEmpty() ? Map.of()
208	                : creditNotes.sumAmountByInvoiceIds(found.stream().map(Invoice::getId).toList()).stream()
209	                        .collect(Collectors.toMap(CreditNoteRepository.InvoiceCreditedTotal::getInvoiceId,
210	                                CreditNoteRepository.InvoiceCreditedTotal::getCredited));
211	    }
