213	    /**
214	     * One page of the invoices across all projects, with the name of the project each one is for,
215	     * narrowed to the given status when one is supplied. Pages are numbered from zero.
216	     */
217	    @Transactional(readOnly = true)
218	    public InvoicePageResponse listAll(InvoiceStatus status, int page, int size) {
219	        PageRequest request = PageRequest.of(page, size);
220	        Page<Invoice> found = status == null ? invoices.findPageWithProject(request)
221	                : invoices.findPageWithProjectByStatus(status, request);
222	        return InvoicePageResponse.from(found);
223	    }
