225	    @Transactional
226	    public InvoiceResponse create(Long projectId, InvoiceRequest request) {
227	        Project project = projects.findById(projectId)
228	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "Unknown job"));
229	        if (project.isClosed()) {
230	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The job is closed; no new invoice can be raised on it");
231	        }
232	        LocalDate issued = request.issuedDate() != null ? request.issuedDate() : LocalDate.now();
233	        LocalDate due = request.dueDate() != null ? request.dueDate() : issued.plusDays(InvoiceRequest.DEFAULT_TERM_DAYS);
234	        if (due.isBefore(issued)) {
235	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "Due date must not be before the issue date");
236	        }
237	        Invoice invoice = new Invoice(project, issued, due);
238	        if (request.amount() != null) {
239	            invoice.addLineItem(InvoiceRequest.SINGLE_AMOUNT_DESCRIPTION, BigDecimal.ONE, null, request.amount());
240	        }
241	        invoice.applyTax(request.taxPct() != null ? request.taxPct() : settings.defaultTaxPct());
242	        // A new invoice starts with the client's standard discount, if they have one.
243	        BigDecimal defaultDiscountPct = project.getClient().getDefaultDiscountPct();
244	        if (defaultDiscountPct.signum() > 0) {
245	            invoice.addDiscount(defaultDiscountPct, BigDecimal.ZERO);
246	        }
247	        Invoice saved = invoices.save(invoice);
248	        return InvoiceResponse.from(saved, BigDecimal.ZERO, BigDecimal.ZERO);
249	    }
