251	    /** A single invoice with its line items. */
252	    @Transactional(readOnly = true)
253	    public InvoiceDetailResponse get(Long projectId, Long invoiceId) {
254	        Invoice invoice = find(projectId, invoiceId);
255	        return detail(invoice, invoice.statusFor(payments.sumAmountByInvoiceId(invoiceId),
256	                creditNotes.sumAmountByInvoiceId(invoiceId)));
257	    }
