259	    /** Adds a line item to a draft invoice and reworks the invoice amount to match. */
260	    @Transactional
261	    public InvoiceDetailResponse addLineItem(Long projectId, Long invoiceId, LineItemRequest request) {
262	        Invoice invoice = findDraft(projectId, invoiceId);
263	        invoice.addLineItem(request.description().strip(), request.qty(), request.normalizedUnit(), request.unitPrice(),
264	                request.exempt(), request.lineDiscountPct());
265	        invoices.flush();
266	        return detail(invoice);
267	    }
268	
269	    /** Changes a line item on a draft invoice and reworks the invoice amount to match. */
270	    @Transactional
271	    public InvoiceDetailResponse updateLineItem(Long projectId, Long invoiceId, Long lineItemId,
272	            LineItemRequest request) {
273	        Invoice invoice = findDraft(projectId, invoiceId);
274	        InvoiceLineItem item = findLineItem(invoice, lineItemId);
275	        invoice.updateLineItem(item, request.description().strip(), request.qty(), request.normalizedUnit(),
276	                request.unitPrice(), request.exempt(), request.lineDiscountPct());
277	        invoices.flush();
278	        return detail(invoice);
279	    }
280	
281	    /** Removes a line item from a draft invoice and reworks the invoice amount to match. */
282	    @Transactional
283	    public InvoiceDetailResponse removeLineItem(Long projectId, Long invoiceId, Long lineItemId) {
284	        Invoice invoice = findDraft(projectId, invoiceId);
285	        invoice.removeLineItem(findLineItem(invoice, lineItemId));
286	        invoices.flush();
287	        return detail(invoice);
288	    }
289	
290	    /** Replaces the discounts on a draft invoice with a single percentage or flat one and reworks the invoice amount to match. */
291	    @Transactional
