116	    /**
117	     * How old a client's debt is as at today: what is left to pay on each owed invoice (not a draft, void or written
118	     * off) counted against how many days past its due date it is.
119	     */
120	    @Transactional(readOnly = true)
121	    public ClientAgingResponse agingForClient(Long clientId) {
122	        Client client = clients.findById(clientId)
123	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "Unknown client"));
124	        LocalDate today = LocalDate.now(clock);
125	        List<Invoice> found = invoices.findByClientIdWithProject(clientId);
126	        Map<Long, BigDecimal> paid = paidByInvoice(found);
127	        Map<Long, BigDecimal> credited = creditedByInvoice(found);
128	        BigDecimal current = BigDecimal.ZERO.setScale(2);
129	        BigDecimal days30To60 = BigDecimal.ZERO.setScale(2);
130	        BigDecimal days60Plus = BigDecimal.ZERO.setScale(2);
131	        for (Invoice invoice : found) {
132	            BigDecimal invoicePaid = paid.getOrDefault(invoice.getId(), BigDecimal.ZERO);
133	            BigDecimal invoiceCredited = credited.getOrDefault(invoice.getId(), BigDecimal.ZERO);
134	            InvoiceStatus status = invoice.statusFor(invoicePaid, invoiceCredited);
135	            if (status == InvoiceStatus.DRAFT || status.isClosedUnpaid()) {
136	                continue;
137	            }
138	            BigDecimal due = invoice.amountDue(invoicePaid, invoiceCredited);
139	            if (due.signum() <= 0) {
140	                continue;
141	            }
142	            long overdue = invoice.getDueDate() == null ? 0
143	                    : ChronoUnit.DAYS.between(invoice.getDueDate(), today);
144	            if (overdue > 60) {
145	                days60Plus = days60Plus.add(due);
146	            } else if (overdue > 30) {
147	                days30To60 = days30To60.add(due);
148	            } else {
149	                current = current.add(due);
150	            }
151	        }
152	        return new ClientAgingResponse(client.getId(), client.getCurrency(), today,
153	                current.setScale(2, RoundingMode.HALF_UP), days30To60.setScale(2, RoundingMode.HALF_UP),
154	                days60Plus.setScale(2, RoundingMode.HALF_UP));
155	    }
