157	    /**
158	     * The entries on a client's running account. Drafts have not been sent and void invoices were cancelled, so
159	     * neither is charged. A payment made out of held deposits is left out, as the deposit was already credited
160	     * when it was paid in.
161	     */
162	    private List<StatementEntry> accountEntries(Long clientId, List<Invoice> found) {
163	        List<StatementEntry> entries = new ArrayList<>();
164	        List<Long> sent = new ArrayList<>();
165	        for (Invoice invoice : found) {
166	            if (invoice.getStatus() == InvoiceStatus.DRAFT) {
167	                continue;
168	            }
169	            sent.add(invoice.getId());
170	            if (invoice.getStatus() != InvoiceStatus.VOID) {
171	                entries.add(StatementEntry.charge(StatementEntry.Kind.INVOICE, invoice.getId(), invoice.getId(),
172	                        invoice.getIssuedDate(), "Invoice #" + invoice.getId(), invoice.getAmount()));
173	            }
174	        }
175	        if (!sent.isEmpty()) {
176	            for (Payment payment : payments.findByInvoiceIdIn(sent)) {
177	                if (payment.getDepositApplicationId() == null) {
178	                    entries.add(StatementEntry.credit(StatementEntry.Kind.PAYMENT, payment.getId(), payment.getInvoiceId(),
179	                            payment.getDate(), "Payment on invoice #" + payment.getInvoiceId(), payment.getAmount()));
180	                }
181	            }
182	            for (CreditNote note : creditNotes.findByInvoiceIdIn(sent)) {
183	                entries.add(StatementEntry.credit(StatementEntry.Kind.CREDIT_NOTE, note.getId(), note.getInvoiceId(),
184	                        LocalDate.ofInstant(note.getIssuedAt(), ZoneOffset.UTC),
185	                        "Credit note on invoice #" + note.getInvoiceId(), note.getAmount()));
186	            }
187	        }
188	        for (Deposit deposit : deposits.findByClientIdOrderByDateAscIdAsc(clientId)) {
189	            entries.add(StatementEntry.credit(StatementEntry.Kind.DEPOSIT, deposit.getId(), null, deposit.getDate(),
190	                    "Deposit", deposit.getAmount()));
191	        }
192	        for (Refund refund : refunds.findByClientIdOrderByDateDescIdDesc(clientId)) {
193	            entries.add(StatementEntry.charge(StatementEntry.Kind.REFUND, refund.getId(), null, refund.getDate(),
194	                    "Refund", refund.getAmount()));
195	        }
196	        return entries;
197	    }
