325	        invoice.applyTax(request.taxPct());
326	        invoices.flush();
327	        return detail(invoice);
328	    }
329	
330	    /** Sets the levy (second tax) percentage on a draft invoice and reworks the invoice amount to match. */
331	    @Transactional
332	    public InvoiceDetailResponse applyLevy(Long projectId, Long invoiceId, LevyRequest request) {
333	        Invoice invoice = findDraft(projectId, invoiceId);
334	        invoice.applyLevy(request.levyPct());
335	        invoices.flush();
336	        return detail(invoice);
337	    }
338	
339	    /** Sets the flat surcharge on a draft invoice and reworks the invoice amount to match. */
340	    @Transactional
341	    public InvoiceDetailResponse applySurcharge(Long projectId, Long invoiceId, SurchargeRequest request) {
342	        Invoice invoice = findDraft(projectId, invoiceId);
343	        invoice.applySurcharge(request.surcharge());
344	        invoices.flush();
345	        return detail(invoice);
346	    }
347	
348	    /** Sets the minimum charge on a draft invoice and reworks the invoice amount to match. */
349	    @Transactional
350	    public InvoiceDetailResponse applyMinimumCharge(Long projectId, Long invoiceId, MinimumChargeRequest request) {
351	        Invoice invoice = findDraft(projectId, invoiceId);
352	        invoice.applyMinimumCharge(request.minimumCharge());
353	        invoices.flush();
354	        return detail(invoice);
355	    }
356	
357	    /** Sets the early-payment discount offered on a draft invoice. */
358	    @Transactional
359	    public InvoiceDetailResponse applyEarlyPayment(Long projectId, Long invoiceId, EarlyPaymentRequest request) {
360	        Invoice invoice = findDraft(projectId, invoiceId);
361	        invoice.applyEarlyPayment(request.earlyPaymentPct(), request.earlyPaymentDays());
362	        invoices.flush();
363	        return detail(invoice);
364	    }
365	
366	    /** Sets the late fee charged for each day a draft invoice is overdue once it has been sent. */
367	    @Transactional
368	    public InvoiceDetailResponse applyLateFee(Long projectId, Long invoiceId, LateFeeRequest request) {
369	        Invoice invoice = findDraft(projectId, invoiceId);
370	        invoice.applyLateFee(request.lateFeePerDay());
371	        invoices.flush();
372	        return detail(invoice);
373	    }
374	
375	    /** Sends a draft invoice and records the sending in the audit log. */
376	    @Transactional
377	    public InvoiceResponse send(Long projectId, Long invoiceId) {
378	        Invoice invoice = find(projectId, invoiceId);
379	        if (invoice.getStatus() != InvoiceStatus.DRAFT) {
380	            throw new ResponseStatusException(HttpStatus.CONFLICT, "Only a draft invoice can be sent");
381	        }
382	        if (invoice.getAmount().signum() == 0) {
383	            throw new ResponseStatusException(HttpStatus.CONFLICT, "Add a line item before sending the invoice");
384	        }
385	        invoice.markSent();
386	        invoices.flush();
387	        audit.record("INVOICE_SENT id=" + invoice.getId() + " amount=" + invoice.getAmount().toPlainString());
388	        return toResponse(invoice);
389	    }
390	
391	    /**
392	     * Cancels an invoice sent by mistake, so it no longer counts toward what is owed, and records the
393	     * cancellation in the audit log. Only a sent invoice with nothing yet paid against it can be voided.
394	     */
395	    @Transactional
396	    public InvoiceResponse cancel(Long projectId, Long invoiceId) {
397	        Invoice invoice = find(projectId, invoiceId);
398	        if (invoice.getStatus() != InvoiceStatus.SENT) {
399	            throw new ResponseStatusException(HttpStatus.CONFLICT,
400	                    "Only a sent invoice with no payments recorded can be cancelled");
401	        }
402	        invoice.markVoid();
403	        invoices.flush();
404	        audit.record("INVOICE_VOIDED id=" + invoice.getId() + " amount=" + invoice.getAmount().toPlainString());
405	        return toResponse(invoice);
406	    }
407	
408	    /**
409	     * Writes off a sent or part-paid invoice as bad debt, so what is left on it no longer counts toward what is
410	     * owed while the invoice stays on record, and records the write-off (the balance given up) in the audit log.
411	     */
412	    @Transactional
413	    public InvoiceDetailResponse writeOff(Long projectId, Long invoiceId) {
414	        Invoice invoice = find(projectId, invoiceId);
415	        BigDecimal paid = payments.sumAmountByInvoiceId(invoiceId);
416	        BigDecimal credited = creditNotes.sumAmountByInvoiceId(invoiceId);
417	        if (!invoice.statusFor(paid, credited).isOwing()) {
418	            throw new ResponseStatusException(HttpStatus.CONFLICT,
419	                    "Only a sent invoice with something still owed can be written off");
420	        }
421	        BigDecimal balance = invoice.amountDue(paid, credited);
422	        invoice.markWrittenOff();
423	        invoices.flush();
424	        audit.record("INVOICE_WRITTEN_OFF id=" + invoice.getId() + " amount=" + balance.setScale(2).toPlainString());
425	        return detail(invoice);
426	    }
427	
428	    private InvoiceResponse toResponse(Invoice invoice) {
429	        return InvoiceResponse.from(invoice, payments.sumAmountByInvoiceId(invoice.getId()),
430	                creditNotes.sumAmountByInvoiceId(invoice.getId()));
431	    }
432	
433	    private Invoice find(Long projectId, Long invoiceId) {
434	        return invoices.findById(invoiceId)
435	                .filter(i -> i.getProject().getId().equals(projectId))
436	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "Unknown invoice"));
437	    }
438	
439	    private Invoice findDraft(Long projectId, Long invoiceId) {
440	        Invoice invoice = find(projectId, invoiceId);
441	        if (invoice.getStatus() != InvoiceStatus.DRAFT) {
442	            throw new ResponseStatusException(HttpStatus.CONFLICT, "Only a draft invoice can be changed");
443	        }
444	        return invoice;
445	    }
446	
447	    private static InvoiceLineItem findLineItem(Invoice invoice, Long lineItemId) {
448	        return invoice.findLineItem(lineItemId)
449	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "Unknown line item"));
450	    }
451	
452	    private InvoiceDetailResponse detail(Invoice invoice) {
453	        return detail(invoice, invoice.getStatus());
454	    }
455	
456	    /**
457	     * The invoice in full; a foreign invoice also converted into the home currency at the exchange rate
458	     * from its issue date, so a later rate never changes what it was worth.
459	     */
460	    private InvoiceDetailResponse detail(Invoice invoice, InvoiceStatus status) {
461	        String home = settings.homeCurrency();
462	        String currency = invoice.getProject().getClient().getCurrency();
463	        BigDecimal homeAmount = currency.equals(home) ? null
464	                : fxRates.toHome(currency, invoice.getIssuedDate(), invoice.getAmount()).orElse(null);
465	        return InvoiceDetailResponse.from(invoice, status, home, homeAmount, LocalDate.now(clock));
466	    }
467	}

