 23	import org.springframework.http.HttpStatus;
 24	import org.springframework.stereotype.Service;
 25	import org.springframework.transaction.annotation.Transactional;
 26	import org.springframework.web.server.ResponseStatusException;
 27	
 28	@Service
 29	public class PaymentService {
 30	
 31	    private final PaymentRepository payments;
 32	    private final CreditNoteRepository creditNotes;
 33	    private final InvoiceRepository invoices;
 34	    private final ClientPaymentRepository clientPayments;
 35	    private final DepositApplicationRepository depositApplications;
 36	    private final ClientCreditService credit;
 37	    private final ClientRepository clients;
 38	    private final Clock clock;
 39	    private final Audit audit;
 40	
 41	    public PaymentService(PaymentRepository payments, CreditNoteRepository creditNotes, InvoiceRepository invoices,
 42	            ClientPaymentRepository clientPayments, DepositApplicationRepository depositApplications,
 43	            ClientCreditService credit, ClientRepository clients, Clock clock, Audit audit) {
 44	        this.payments = payments;
 45	        this.creditNotes = creditNotes;
 46	        this.invoices = invoices;
 47	        this.clientPayments = clientPayments;
 48	        this.depositApplications = depositApplications;
 49	        this.credit = credit;
 50	        this.clients = clients;
 51	        this.clock = clock;
 52	        this.audit = audit;
 53	    }
 54	
 55	    @Transactional(readOnly = true)
 56	    public List<PaymentResponse> list(Long projectId, Long invoiceId) {
 57	        find(projectId, invoiceId);
 58	        return payments.findByInvoiceIdOrderByDateAscIdAsc(invoiceId).stream().map(PaymentResponse::from).toList();
 59	    }
 60	
 61	    /**
 62	     * Records a payment against an invoice that has been sent to the client and is still owing, and
 63	     * works out the invoice's status from what has now been paid and credited. A payment may not take
 64	     * the total paid and credited beyond the invoice amount.
 65	     */
 66	    @Transactional
 67	    public PaymentResponse record(Long projectId, Long invoiceId, PaymentRequest request) {
 68	        Invoice invoice = find(projectId, invoiceId);
 69	        return apply(invoice, request.amount(), () -> new Payment(invoice.getId(), request.amount(), request.date()));
 70	    }
 71	
 72	    /**
 73	     * Records one lump payment from a client split across several of their owing invoices. With
 74	     * {@code useCredit} the client's credit is used up first (held deposits, then unused credit
 75	     * notes) and the money received covers the rest; otherwise the money received covers it all.
 76	     * The shares may not add up to more than the money received plus any credit used, and whatever
 77	     * of the money received is left over is kept as credit for the client, so the money received
 78	     * plus the credit used always equals the shares plus what is kept. Each invoice may appear
 79	     * once, and each share is recorded as a payment against its own invoice under the same rules
 80	     * as a payment made on its own.
 81	     */
 82	    @Transactional
 83	    public ClientPaymentResponse recordForClient(Long clientId, ClientPaymentRequest request) {
 84	        requireClient(clientId);
 85	        BigDecimal allocated = total(request.allocations(), ClientPaymentRequest.Allocation::amount).setScale(2);
 86	        BigDecimal received = request.amount().setScale(2);
 87	        BigDecimal fromDeposits = BigDecimal.ZERO.setScale(2);
 88	        BigDecimal fromCreditNotes = BigDecimal.ZERO.setScale(2);
 89	        if (request.usesCredit()) {
 90	            ClientCreditResponse available = credit.available(clientId);
 91	            fromDeposits = allocated.min(available.deposits());
 92	            fromCreditNotes = allocated.subtract(fromDeposits).min(available.creditNotes());
 93	        }
 94	        BigDecimal fromReceived = allocated.subtract(fromDeposits).subtract(fromCreditNotes);
 95	        if (fromReceived.compareTo(received) > 0) {
 96	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, request.usesCredit()
 97	                    ? "The shares add up to more than the payment and the credit available"
 98	                    : "The shares add up to more than the payment");
 99	        }
100	        BigDecimal toCredit = received.subtract(fromReceived);
101	        requireDistinct(request.allocations(), ClientPaymentRequest.Allocation::invoiceId);
102	        ClientPayment lump = clientPayments.saveAndFlush(new ClientPayment(clientId, received, request.date(),
103	                fromDeposits, fromCreditNotes, toCredit));
104	        List<PaymentResponse> shares = request.allocations().stream()
105	                .map(a -> apply(findForClient(clientId, a.invoiceId()), a.amount(),
106	                        () -> new Payment(a.invoiceId(), a.amount(), request.date(), lump.getId())))
107	                .toList();
108	        audit.record("CLIENT_PAYMENT_RECORDED id=" + lump.getId() + " client=" + clientId
109	                + " amount=" + lump.getAmount().toPlainString()
110	                + " fromDeposits=" + lump.getFromDeposits().toPlainString()
111	                + " fromCreditNotes=" + lump.getFromCreditNotes().toPlainString()
112	                + " toCredit=" + lump.getToCredit().toPlainString());
113	        return ClientPaymentResponse.from(lump, shares);
114	    }
115	
116	    /**
117	     * Puts part of a client's held deposits toward several of their owing invoices, today. The
118	     * shares may not add up to more than is still held, each invoice may appear once, and each share
119	     * is recorded as a payment against its own invoice under the same rules as a lump payment's.
120	     */
121	    @Transactional
122	    public DepositApplicationResponse applyDeposits(Long clientId, DepositApplicationRequest request) {
123	        requireClient(clientId);
124	        BigDecimal allocated = total(request.allocations(), DepositApplicationRequest.Allocation::amount);
125	        BigDecimal held = credit.heldDeposits(clientId);
126	        if (allocated.compareTo(held) > 0) {
127	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
128	                    "The shares add up to more than the deposits held");
129	        }
130	        requireDistinct(request.allocations(), DepositApplicationRequest.Allocation::invoiceId);
131	        LocalDate today = LocalDate.now(clock);
132	        DepositApplication application = depositApplications.saveAndFlush(
133	                new DepositApplication(clientId, allocated, today));
134	        List<PaymentResponse> shares = request.allocations().stream()
135	                .map(a -> apply(findForClient(clientId, a.invoiceId()), a.amount(),
136	                        () -> Payment.fromDeposits(a.invoiceId(), a.amount(), today, application.getId())))
137	                .toList();
138	        audit.record("DEPOSIT_APPLIED id=" + application.getId() + " client=" + clientId
139	                + " amount=" + application.getAmount().toPlainString());
140	        return DepositApplicationResponse.from(application, shares);
141	    }
142	
143	    private void requireClient(Long clientId) {
144	        if (!clients.existsById(clientId)) {
145	            throw new ResponseStatusException(HttpStatus.NOT_FOUND, "Unknown client");
146	        }
147	    }
148	
149	    private static <A> BigDecimal total(List<A> allocations, Function<A, BigDecimal> amount) {
150	        return allocations.stream().map(amount).reduce(BigDecimal.ZERO, BigDecimal::add);
151	    }
152	
153	    private static <A> void requireDistinct(List<A> allocations, Function<A, Long> invoiceId) {
154	        Set<Long> seen = new HashSet<>();
155	        for (A a : allocations) {
156	            if (!seen.add(invoiceId.apply(a))) {
157	                throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "Each invoice may be paid only once");
158	            }
159	        }
160	    }
161	
162	    private PaymentResponse apply(Invoice invoice, BigDecimal amount, Supplier<Payment> payment) {
163	        if (invoice.getStatus() == InvoiceStatus.DRAFT) {
164	            throw new ResponseStatusException(HttpStatus.CONFLICT, "Send the invoice before recording a payment");
165	        }
166	        if (invoice.getStatus() == InvoiceStatus.VOID) {
167	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The invoice has been cancelled");
168	        }
169	        if (invoice.getStatus() == InvoiceStatus.WRITTEN_OFF) {
170	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The invoice has been written off");
171	        }
172	        if (!invoice.getStatus().isOwing()) {
173	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The invoice is already paid");
174	        }
175	        BigDecimal paid = payments.sumAmountByInvoiceId(invoice.getId()).add(amount);
176	        BigDecimal credited = creditNotes.sumAmountByInvoiceId(invoice.getId());
177	        BigDecimal settled = paid.add(credited);
178	        if (settled.compareTo(invoice.getAmount()) > 0) {
179	            throw new ResponseStatusException(HttpStatus.CONFLICT, "Payment is more than the balance due");
180	        }
181	        Payment saved = payments.saveAndFlush(payment.get());
182	        invoice.applySettledTotals(paid, credited);
183	        invoices.flush();
184	        audit.record("PAYMENT_RECORDED id=" + saved.getId() + " amount=" + saved.getAmount().toPlainString());
185	        return PaymentResponse.from(saved);
186	    }
187	
188	    private Invoice findForClient(Long clientId, Long invoiceId) {
189	        return invoices.findById(invoiceId)
190	                .filter(i -> i.getProject().getClient().getId().equals(clientId))
191	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "Unknown invoice"));
192	    }
193	
194	    private Invoice find(Long projectId, Long invoiceId) {
195	        return invoices.findById(invoiceId)
196	                .filter(i -> i.getProject().getId().equals(projectId))
197	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "Unknown invoice"));
198	    }
199	}
