293	
294	@Service
295	public class ClientCreditService {
296	
297	    private static final BigDecimal ZERO = BigDecimal.ZERO.setScale(2);
298	
299	    private final ClientRepository clients;
300	    private final DepositRepository deposits;
301	    private final DepositApplicationRepository applications;
302	    private final InvoiceRepository invoices;
303	    private final PaymentRepository payments;
304	    private final CreditNoteRepository creditNotes;
305	    private final RefundRepository refunds;
306	    private final ClientPaymentRepository clientPayments;
307	
308	    public ClientCreditService(ClientRepository clients, DepositRepository deposits,
309	            DepositApplicationRepository applications, InvoiceRepository invoices, PaymentRepository payments,
310	            CreditNoteRepository creditNotes, RefundRepository refunds, ClientPaymentRepository clientPayments) {
311	        this.clients = clients;
312	        this.deposits = deposits;
313	        this.applications = applications;
314	        this.invoices = invoices;
315	        this.payments = payments;
316	        this.creditNotes = creditNotes;
317	        this.refunds = refunds;
318	        this.clientPayments = clientPayments;
319	    }
320	
321	    /**
322	     * Works out how much credit a client has to spend. A deposit is unused until it is put toward invoices. A credit
323	     * note is used only as far as it was needed to settle its invoice once payments are counted; anything beyond
324	     * that (say, a credit on an invoice already paid in full, or on one since cancelled) is still the client's to spend.
325	     * Whatever has been refunded to the client, or used up by a payment of theirs, is no longer theirs to spend; what
326	     * a payment brought in beyond what its invoices needed is held for them alongside their deposits.
327	     */
328	    @Transactional(readOnly = true)
329	    public ClientCreditResponse available(Long clientId) {
330	        if (!clients.existsById(clientId)) {
331	            throw new ResponseStatusException(HttpStatus.NOT_FOUND, "Unknown client");
332	        }
333	        BigDecimal held = heldDeposits(clientId);
334	        BigDecimal unusedCredit = unusedCreditNotes(clientId)
335	                .subtract(refunds.sumFromCreditNotesByClientId(clientId))
336	                .subtract(clientPayments.sumFromCreditNotesByClientId(clientId)).setScale(2).max(ZERO);
337	        return new ClientCreditResponse(held, unusedCredit, held.add(unusedCredit));
338	    }
339	
340	    /**
341	     * What a client still has held in deposits: everything paid up front plus whatever their payments brought in
342	     * beyond what their invoices needed, less what has been put toward invoices, used up by payments or refunded.
343	     */
344	    @Transactional(readOnly = true)
345	    public BigDecimal heldDeposits(Long clientId) {
346	        return deposits.sumAmountByClientId(clientId)
347	                .add(clientPayments.sumToCreditByClientId(clientId))
348	                .subtract(applications.sumAmountByClientId(clientId))
349	                .subtract(clientPayments.sumFromDepositsByClientId(clientId))
350	                .subtract(refunds.sumFromDepositsByClientId(clientId)).setScale(2).max(ZERO);
351	    }
352	
353	    private BigDecimal unusedCreditNotes(Long clientId) {
354	        List<Invoice> clientInvoices = invoices.findByClientIdWithProject(clientId);
355	        List<Long> ids = clientInvoices.stream().map(Invoice::getId).toList();
356	        if (ids.isEmpty()) {
357	            return ZERO;
358	        }
359	        Map<Long, BigDecimal> credited = creditNotes.sumAmountByInvoiceIds(ids).stream().collect(Collectors.toMap(
360	                CreditNoteRepository.InvoiceCreditedTotal::getInvoiceId,
361	                CreditNoteRepository.InvoiceCreditedTotal::getCredited));
362	        if (credited.isEmpty()) {
363	            return ZERO;
364	        }
365	        Map<Long, BigDecimal> paid = payments.sumAmountByInvoiceIds(ids).stream().collect(Collectors.toMap(
366	                PaymentRepository.InvoicePaidTotal::getInvoiceId, PaymentRepository.InvoicePaidTotal::getPaid));
367	        BigDecimal unused = ZERO;
368	        for (Invoice invoice : clientInvoices) {
369	            BigDecimal credit = credited.get(invoice.getId());
370	            if (credit == null) {
371	                continue;
372	            }
373	            // A cancelled invoice is no longer owed, so none of its credit went toward settling it.
374	            BigDecimal owed = invoice.getStatus() == InvoiceStatus.VOID ? ZERO
375	                    : invoice.getAmount().subtract(paid.getOrDefault(invoice.getId(), ZERO)).max(ZERO);
376	            unused = unused.add(credit.subtract(credit.min(owed)));
377	        }
378	        return unused.setScale(2);
379	    }
380	}

