 34	    @Transactional(readOnly = true)
 35	    public ClientDepositsResponse list(Long clientId) {
 36	        requireClient(clientId);
 37	        List<DepositResponse> held = deposits.findByClientIdOrderByDateAscIdAsc(clientId).stream()
 38	                .map(DepositResponse::from).toList();
 39	        BigDecimal paid = held.stream().map(DepositResponse::amount)
 40	                .reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
 41	        // Overpayments kept as credit are held alongside the deposits; deposits used up by payments count as applied.
 42	        BigDecimal overpaid = clientPayments.sumToCreditByClientId(clientId).setScale(2);
 43	        BigDecimal applied = applications.sumAmountByClientId(clientId)
 44	                .add(clientPayments.sumFromDepositsByClientId(clientId)).setScale(2);
 45	        BigDecimal refunded = refunds.sumFromDepositsByClientId(clientId).setScale(2);
 46	        return new ClientDepositsResponse(paid.add(overpaid).subtract(applied).subtract(refunded), applied, refunded,
 47	                held);
 48	    }
