 99	    @Transactional(readOnly = true)
100	    public List<RefundResponse> list(Long clientId) {
101	        if (!clients.existsById(clientId)) {
102	            throw new ResponseStatusException(HttpStatus.NOT_FOUND, "Unknown client");
103	        }
104	        return refunds.findByClientIdOrderByDateDescIdDesc(clientId).stream().map(RefundResponse::from).toList();
105	    }
106	
107	    /**
108	     * Pays part of a client's unused credit back to them, today. It may not be more than the credit
109	     * they have; it comes out of their held deposits first, then their unused credit notes.
110	     */
111	    @Transactional
112	    public RefundResponse refund(Long clientId, RefundRequest request) {
113	        ClientCreditResponse available = credit.available(clientId);
