 43	        BigDecimal applied = applications.sumAmountByClientId(clientId)
 44	                .add(clientPayments.sumFromDepositsByClientId(clientId)).setScale(2);
 45	        BigDecimal refunded = refunds.sumFromDepositsByClientId(clientId).setScale(2);
 46	        return new ClientDepositsResponse(paid.add(overpaid).subtract(applied).subtract(refunded), applied, refunded,
 47	                held);
 48	    }
