  2	
  3	import java.math.BigDecimal;
  4	import java.time.LocalDate;
  5	import java.util.List;
  6	
  7	/**
  8	 * A single invoice together with the line items it is built from: their subtotal, each discount on it
  9	 * (with what it takes off), the percentage discounts and flat amount discounts added up, and what they all take off together, the sales tax percentage, the taxable base it is charged on (the
 10	 * taxable lines after the discount) and what it adds, the levy (second tax) percentage and what it adds
 11	 * on the same base, any flat surcharge (such as a handling fee) added after tax, the amount owed including both taxes and the surcharge, the total before tax, whether the prices already include the taxes
 12	 * (so they are worked back out rather than added on), whether the client is tax exempt (so
 13	 * there is no tax at all), the effective tax rate (the sales tax and levy together as a percentage of
 14	 * the total before tax), any early-payment discount offered (its percentage, the days after issue it
 15	 * must be paid within, the last day to pay, and the reduced amount; null when none is offered), and the
 16	 * client's tax number (null when the client is not tax registered), the minimum charge, the net total
 17	 * before it, whether the minimum was billed because the net total came out under it, and the total
 18	 * savings (the line discounts and the invoice's discounts added together). A foreign invoice also gives
 19	 * the home currency and its amount converted into it at the exchange rate from the invoice's issue date
 20	 * (null when the invoice is already in the home currency or there is no rate for that date). The late
 21	 * fee charged per day overdue, the days the invoice is overdue as of today (only while sent and still
 22	 * owed), and the late fee that has accrued over them.
 23	 */
 24	public record InvoiceDetailResponse(Long id, Long projectId, String currency, BigDecimal amount, BigDecimal totalExTax,
 25	        BigDecimal subtotal,
 26	        BigDecimal discountPct, BigDecimal discountAmount, BigDecimal discount, BigDecimal taxPct, BigDecimal taxableBase, BigDecimal tax,
 27	        BigDecimal levyPct, BigDecimal levy, BigDecimal surcharge, boolean taxInclusive, boolean taxExempt, BigDecimal effectiveTaxPct,
 28	        BigDecimal earlyPaymentPct, int earlyPaymentDays, LocalDate earlyPaymentBy, BigDecimal earlyPaymentAmount,
 29	        InvoiceStatus status, LocalDate issuedDate,
 30	        LocalDate dueDate, List<LineItemResponse> lineItems, String clientTaxNumber, List<InvoiceDiscountResponse> discounts,
 31	        BigDecimal minimumCharge, BigDecimal netTotal, boolean minimumApplied, BigDecimal totalSavings,
 32	        String homeCurrency, BigDecimal homeAmount,
 33	        BigDecimal lateFeePerDay, long daysLate, BigDecimal lateFee) {
 34	
 35	    /**
 36	     * The invoice with the given status, as worked out from what has been paid and credited against it, and
 37	     * its amount in the home currency, with any late fee accrued by today.
 38	     */
 39	    static InvoiceDetailResponse from(Invoice invoice, InvoiceStatus status, String homeCurrency, BigDecimal homeAmount,
 40	            LocalDate today) {
 41	        return new InvoiceDetailResponse(invoice.getId(), invoice.getProject().getId(),
 42	                invoice.getProject().getClient().getCurrency(), invoice.getAmount(), invoice.getTotalExTax(),
 43	                invoice.getSubtotal(), invoice.getDiscountPct(), invoice.getDiscountAmount(), invoice.getDiscount(),
 44	                invoice.getTaxPct(), invoice.getTaxableBase(), invoice.getTax(),
 45	                invoice.getLevyPct(), invoice.getLevy(), invoice.getSurcharge(), invoice.isTaxInclusive(), invoice.isTaxExempt(),
 46	                invoice.getEffectiveTaxPct(),
 47	                invoice.getEarlyPaymentPct(), invoice.getEarlyPaymentDays(), invoice.getEarlyPaymentBy(),
 48	                invoice.getEarlyPaymentAmount(),
 49	                status, invoice.getIssuedDate(), invoice.getDueDate(),
 50	                invoice.getLineItems().stream().map(LineItemResponse::from).toList(),
 51	                invoice.getProject().getClient().getTaxNumber(),
 52	                invoice.getDiscounts().stream().map(d -> new InvoiceDiscountResponse(d.getId(), d.getDiscountPct(),
 53	                        d.getDiscountAmount(), d.getDiscountCap(), invoice.discountTakenBy(d))).toList(),
 54	                invoice.getMinimumCharge(), invoice.getNetTotal(), invoice.isMinimumApplied(),
 55	                invoice.getTotalSavings(), homeCurrency, homeAmount,
 56	                invoice.getLateFeePerDay(), invoice.daysLate(status, today), invoice.lateFee(status, today));
 57	    }
 58	}
 59	package net.officefloor.hq.app.invoice;
 60	
 61	import java.math.BigDecimal;
 62	import java.time.LocalDate;
 63	
 64	/**
 65	 * An invoice, with how much of it is still left to pay after the payments made and credit notes raised against
 66	 * it (nothing once void), and whether any credit has been put against it.
 67	 */
 68	public record InvoiceResponse(Long id, Long projectId, String currency, BigDecimal amount, InvoiceStatus status,
 69	        LocalDate issuedDate, LocalDate dueDate, BigDecimal amountDue,
 70	        boolean creditApplied) {
 71	
 72	    static InvoiceResponse from(Invoice invoice, BigDecimal paid, BigDecimal credited) {
 73	        return new InvoiceResponse(invoice.getId(), invoice.getProject().getId(),
 74	                invoice.getProject().getClient().getCurrency(), invoice.getAmount(),
 75	                invoice.statusFor(paid, credited), invoice.getIssuedDate(), invoice.getDueDate(),
 76	                invoice.amountDue(paid, credited), credited.signum() > 0);
 77	    }
 78	}
 79	package net.officefloor.hq.app.invoice;
 80	
 81	import java.math.BigDecimal;
 82	import java.math.RoundingMode;
 83	import java.time.LocalDate;
 84	import java.util.ArrayList;
 85	import java.util.LinkedHashMap;
 86	import java.util.List;
 87	import java.util.Map;
 88	import java.util.function.Function;
 89	
 90	/**
 91	 * A client's statement: all of their invoices, each with the project it is for and how much is left
 92	 * to pay, the same invoices grouped by job with what is owed on each job, and the total still owed
 93	 * (what is left to pay across their sent invoices; drafts and void ones are not owed). For the printable
 94	 * summary it also gives the total invoiced on those owed invoices and how much of that has been paid,
 95	 * so the total still owed is what was invoiced less what was paid. It also shows the tax (sales tax and
 96	 * levy) on each job and across the whole statement, again leaving out drafts and void invoices. All of it
 97	 * is in the client's currency. Finally it gives the running account: every invoice, payment, credit note, deposit and
 98	 * refund in date order, each with the balance owed once it is counted.
 99	 */
100	public record ClientStatementResponse(Long clientId, String clientName, String currency, List<Line> invoices, List<Job> jobs,
101	        BigDecimal invoiced, BigDecimal paid, BigDecimal outstanding, BigDecimal tax, List<StatementEntry> entries) {
102	
103	    static ClientStatementResponse from(Long clientId, String clientName, String currency, List<Line> invoices,
104	            List<StatementEntry> entries) {
105	        Map<Long, List<Line>> byProject = new LinkedHashMap<>();
106	        invoices.forEach(l -> byProject.computeIfAbsent(l.projectId(), id -> new ArrayList<>()).add(l));
107	        List<Job> jobs = byProject.values().stream()
108	                .map(lines -> new Job(lines.get(0).projectId(), lines.get(0).projectName(), lines, owed(lines), sum(lines, Line::tax)))
109	                .toList();
110	        BigDecimal outstanding = owed(invoices);
111	        BigDecimal invoiced = sum(invoices, Line::amount);
112	        return new ClientStatementResponse(clientId, clientName, currency, invoices, jobs, invoiced,
113	                invoiced.subtract(outstanding), outstanding, sum(invoices, Line::tax), runningBalance(entries));
114	    }
115	
116	    /** Puts the entries in date order, each carrying the balance owed once it and those before it are counted. */
117	    private static List<StatementEntry> runningBalance(List<StatementEntry> entries) {
118	        List<StatementEntry> ordered = new ArrayList<>();
119	        BigDecimal balance = BigDecimal.ZERO.setScale(2);
120	        for (StatementEntry entry : entries.stream().sorted(StatementEntry.DATE_ORDER).toList()) {
121	            balance = balance.add(entry.change());
122	            ordered.add(entry.withBalance(balance));
123	        }
124	        return ordered;
125	    }
126	
127	    /** What is left to pay across the given invoices, leaving out drafts and void ones. */
128	    private static BigDecimal owed(List<Line> lines) {
129	        return sum(lines, Line::amountDue);
130	    }
131	
132	    /** Adds up the given figure across the invoices that are owed, leaving out drafts and void ones. */
133	    private static BigDecimal sum(List<Line> lines, Function<Line, BigDecimal> figure) {
134	        return lines.stream()
135	                .filter(l -> l.status() != InvoiceStatus.DRAFT && !l.status().isClosedUnpaid())
136	                .map(figure)
137	                .reduce(BigDecimal.ZERO, BigDecimal::add)
138	                .setScale(2, RoundingMode.HALF_UP);
139	    }
140	
141	    /** One job on a statement: its invoices, the subtotal still owed on them and the tax charged on them. */
142	    public record Job(Long projectId, String projectName, List<Line> invoices, BigDecimal subtotal, BigDecimal tax) {
143	    }
144	
145	    /** One invoice on a statement; its tax is the sales tax and levy on it. */
146	    public record Line(Long id, Long projectId, String projectName, BigDecimal amount, InvoiceStatus status,
147	            LocalDate issuedDate, LocalDate dueDate, BigDecimal amountDue, BigDecimal tax) {
148	
149	        static Line from(Invoice invoice, BigDecimal paid, BigDecimal credited) {
150	            return new Line(invoice.getId(), invoice.getProject().getId(), invoice.getProject().getName(),
151	                    invoice.getAmount(), invoice.statusFor(paid, credited), invoice.getIssuedDate(), invoice.getDueDate(),
152	                    invoice.amountDue(paid, credited), invoice.getTax().add(invoice.getLevy()));
153	        }
154	    }
155	}
156	package net.officefloor.hq.app.invoice;
157	
158	import java.math.BigDecimal;
159	import java.time.LocalDate;
160	import java.util.Comparator;
161	
162	/**
163	 * One dated entry on a client's running account. An invoice is a charge; a payment, credit note or deposit is a
164	 * credit; a refund of unused credit is a charge again. The balance is what the client owes once this entry and every
165	 * one before it is counted (negative when the client is in credit). The invoice is the one the entry is for, if any.
166	 */
167	public record StatementEntry(Kind kind, Long sourceId, Long invoiceId, LocalDate date, String description,
168	        BigDecimal charge, BigDecimal credit, BigDecimal balance) {
169	
170	    /** What an entry records, in the order entries on the same day are listed. */
171	    public enum Kind {
172	        INVOICE, PAYMENT, CREDIT_NOTE, DEPOSIT, REFUND
173	    }
174	
175	    /** Date order; on the same day charges come before what was paid against them, then by record id. */
176	    static final Comparator<StatementEntry> DATE_ORDER = Comparator.comparing(StatementEntry::date)
177	            .thenComparing(StatementEntry::kind)
178	            .thenComparing(StatementEntry::sourceId);
179	
180	    static StatementEntry charge(Kind kind, Long sourceId, Long invoiceId, LocalDate date, String description,
181	            BigDecimal amount) {
182	        return new StatementEntry(kind, sourceId, invoiceId, date, description, amount.setScale(2), null, null);
183	    }
184	
185	    static StatementEntry credit(Kind kind, Long sourceId, Long invoiceId, LocalDate date, String description,
186	            BigDecimal amount) {
187	        return new StatementEntry(kind, sourceId, invoiceId, date, description, null, amount.setScale(2), null);
188	    }
189	
190	    /** What this entry adds to what the client owes. */
191	    BigDecimal change() {
192	        return charge != null ? charge : credit.negate();
193	    }
194	
195	    StatementEntry withBalance(BigDecimal balance) {
196	        return new StatementEntry(kind, sourceId, invoiceId, date, description, charge, credit, balance);
197	    }
198	}

