  /**
   * Counts of clients and projects, and the total still owed in each currency (what is left to pay
   * on sent invoices that are not yet fully paid; a currency with written-off invoices is listed even when nothing is owed), plus how many of those sent invoices are past their due date and
   * what is overdue on them (see {@link #overdueAmount}), and the top clients ranked by what they owe.
   */
  @Transactional(readOnly = true)
  public DashboardResponse summary() {
      List<InvoiceStatus> owing = List.of(InvoiceStatus.SENT, InvoiceStatus.PARTIAL);
      Map<String, BigDecimal> owed = new TreeMap<>(Currency.ORDER);
      // A currency whose debts were written off stays listed, showing nothing owed, so the write-off is visible.
      clients.findAllById(invoices.sumAmountByStatusInPerClient(List.of(InvoiceStatus.WRITTEN_OFF)).stream()
              .map(InvoiceRepository.ClientTotal::getClientId).toList())
              .forEach(c -> owed.put(c.getCurrency(), BigDecimal.ZERO));
      owed.putAll(clientService.outstandingByCurrency());
      List<DashboardResponse.CurrencyTotal> outstanding = owed.entrySet().stream()
              .map(e -> new DashboardResponse.CurrencyTotal(e.getKey(), e.getValue().setScale(2, RoundingMode.HALF_UP)))
              .toList();
      LocalDate today = LocalDate.now(clock);
      long overdue = invoices.countByStatusInAndDueDateBefore(owing, today);
      String home = settings.homeCurrency();
      BigDecimal overdueAmount = overdueAmount(invoices.findByStatusInAndDueDateBefore(owing, today), home, today);
      List<DashboardResponse.TopClient> top = clientService.topByOutstanding(TOP_CLIENTS).stream()
              .map(c -> new DashboardResponse.TopClient(c.id(), c.name(), c.currency(), c.outstanding()))
              .toList();
      return new DashboardResponse(clients.count(), projects.count(), outstanding, overdue, home, overdueAmount, top);
  }

  /**
   * What is overdue, in the home currency: what is left to pay on each overdue invoice plus the late fee it
   * has accrued by today. A foreign invoice converts at the exchange rate from its issue date; one whose
   * currency has no rate by then cannot be converted and is left out.
   */
  private BigDecimal overdueAmount(List<Invoice> found, String home, LocalDate today) {
      if (found.isEmpty()) {
          return BigDecimal.ZERO.setScale(2);
      }
      List<Long> ids = found.stream().map(Invoice::getId).toList();
      Map<Long, BigDecimal> paid = payments.sumAmountByInvoiceIds(ids).stream()
              .collect(Collectors.toMap(PaymentRepository.InvoicePaidTotal::getInvoiceId,
                      PaymentRepository.InvoicePaidTotal::getPaid));
      Map<Long, BigDecimal> credited = creditNotes.sumAmountByInvoiceIds(ids).stream()
              .collect(Collectors.toMap(CreditNoteRepository.InvoiceCreditedTotal::getInvoiceId,
                      CreditNoteRepository.InvoiceCreditedTotal::getCredited));
      BigDecimal total = BigDecimal.ZERO;
      for (Invoice invoice : found) {
          BigDecimal due = invoice.amountDue(paid.getOrDefault(invoice.getId(), BigDecimal.ZERO),
                  credited.getOrDefault(invoice.getId(), BigDecimal.ZERO))
                  .add(invoice.lateFee(invoice.getStatus(), today));
          String currency = invoice.getProject().getClient().getCurrency();
          BigDecimal inHome = currency.equals(home) ? due
                  : fxRates.toHome(currency, invoice.getIssuedDate(), due).orElse(BigDecimal.ZERO);
          total = total.add(inHome);
      }
      return total.setScale(2, RoundingMode.HALF_UP);
  }


  /** Invoices that have been issued to the client: everything but drafts and cancelled invoices. */
  private static final List<InvoiceStatus> BILLED = List.of(InvoiceStatus.SENT, InvoiceStatus.PARTIAL,
          InvoiceStatus.PAID, InvoiceStatus.WRITTEN_OFF);

  /** At-a-glance counts of what one client has, and the total ever billed to them. */
  @Transactional(readOnly = true)
  public ClientSummaryResponse summary(Long id) {
      if (!clients.existsById(id)) {
          throw new ResponseStatusException(HttpStatus.NOT_FOUND, "Unknown client");
      }
      BigDecimal billed = invoices.sumAmountByClientIdAndStatusIn(id, BILLED).setScale(2, RoundingMode.HALF_UP);
      return new ClientSummaryResponse(projects.countByClientId(id), contacts.countByClientId(id), billed);
  }

  /** Adds a client; its email, once trimmed, must not already belong to another client. */
  @Transactional
  public ClientResponse create(ClientRequest request) {
      String email = request.email().trim();
      if (clients.existsByEmailIgnoreCase(email)) {
          throw emailTaken();
  /**
   * The clients who owe the most, largest debt first (ties by id), at most {@code limit} of them.
   * Clients owing nothing are left out.
   */
  @Transactional(readOnly = true)
  public List<ClientResponse> topByOutstanding(int limit) {
      Map<Long, BigDecimal> owed = outstandingByClient();
      owed.values().removeIf(amount -> amount.signum() <= 0);
      List<Long> top = owed.entrySet().stream()
              .sorted(Map.Entry.<Long, BigDecimal>comparingByValue().reversed()
                      .thenComparing(Map.Entry.comparingByKey()))
              .limit(limit)
              .map(Map.Entry::getKey)
              .toList();
      Map<Long, Client> found = new HashMap<>();
      clients.findAllById(top).forEach(c -> found.put(c.getId(), c));
      return top.stream().map(id -> ClientResponse.from(found.get(id), owed.get(id))).toList();
  }

  /**
   * What is still owed in each currency, each client's debt counted in their own currency; amounts
   * in different currencies are never added together. Currencies nothing is owed in are left out.
   */
  @Transactional(readOnly = true)
  public Map<String, BigDecimal> outstandingByCurrency() {
      Map<Long, BigDecimal> owed = outstandingByClient();
      Map<String, BigDecimal> totals = new TreeMap<>(Currency.ORDER);
      clients.findAllById(owed.keySet())
              .forEach(c -> totals.merge(c.getCurrency(), owed.get(c.getId()), BigDecimal::add));
      totals.values().removeIf(amount -> amount.signum() == 0);
      return totals;
  }

  private ClientResponse respond(Client client) {
      return ClientResponse.from(client, outstandingByClient().getOrDefault(client.getId(), ZERO));
  }

  /**
   * What each client still owes: what is left to pay on their sent invoices that are not yet fully
   * paid, after the payments and credit notes against them. Clients owing nothing are left out.
   */
  private Map<Long, BigDecimal> outstandingByClient() {
      List<InvoiceStatus> owing = List.of(InvoiceStatus.SENT, InvoiceStatus.PARTIAL);
      Map<Long, BigDecimal> owed = new HashMap<>();
      invoices.sumAmountByStatusInPerClient(owing).forEach(t -> owed.merge(t.getClientId(), t.getTotal(),
              BigDecimal::add));
      payments.sumAmountByInvoiceStatusInPerClient(owing).forEach(t -> owed.merge(t.getClientId(),
              t.getTotal().negate(), BigDecimal::add));
      creditNotes.sumAmountByInvoiceStatusInPerClient(owing).forEach(t -> owed.merge(t.getClientId(),
              t.getTotal().negate(), BigDecimal::add));
      owed.replaceAll((id, amount) -> amount.setScale(2, RoundingMode.HALF_UP));
      return owed;
  }

  private Client find(Long id) {
private readonly injector = inject(Injector);
private readonly fb = inject(NonNullableFormBuilder);

/** Bound from the `:projectId` route parameter. */
readonly projectId = input.required<string>();
/** Bound from the `:invoiceId` route parameter. */
readonly invoiceId = input.required<string>();
protected readonly projectIdNumber = computed(() => Number(this.projectId()));

protected readonly invoice = rxResource({
  params: () => ({ projectId: this.projectIdNumber(), invoiceId: Number(this.invoiceId()) }),
  stream: ({ params }) => this.service.get(params.projectId, params.invoiceId),
});

// The credit notes reduce what is left to pay alongside the payments.
protected readonly creditNotes = rxResource({
  params: () => ({ projectId: this.projectIdNumber(), invoiceId: Number(this.invoiceId()) }),
  stream: ({ params }) => this.creditNoteService.list(params.projectId, params.invoiceId),
});
protected readonly credited = computed(
  () =>
    (this.creditNotes.hasValue() ? this.creditNotes.value() : []).reduce((sum, c) => sum + Math.round(c.amount * 100), 0) /
    100,
);

// Work in whole cents (and ten-thousandths of a unit price) so the line is exact rather than
// accumulating floating-point error; each line, and then its own discount, is rounded to the cent on its own.
protected lineCents(qty: number, unitPrice: number, discountPct: number): number {
  const gross = Math.round((Math.round(qty * 100) * Math.round(unitPrice * 10000)) / 10000);
  return gross - Math.round((gross * Math.round(discountPct * 100)) / 10000);
}

protected readonly writingOff = signal(false);
protected readonly writeOffError = signal<string | null>(null);

// Writes the invoice off as bad debt: it is kept on record but no longer counts toward what is owed.
protected writeOff(): void {
  this.writingOff.set(true);
  this.writeOffError.set(null);
  this.service.writeOff(this.projectIdNumber(), Number(this.invoiceId())).subscribe({
    next: (updated) => {
      this.invoice.set(updated);
      this.writingOff.set(false);
    },
    error: () => {
      this.writeOffError.set('Could not write off the invoice. Please try again.');
      this.writingOff.set(false);
    },
  });
}

protected readonly discountSaving = signal(false);
protected readonly discountError = signal<string | null>(null);

protected readonly discountForm = this.fb.group({
